document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('quiz-form');
    const resultsContainer = document.getElementById('results');

    // Define correct answers (arrays for multiple choices)
    const correctAnswers = {
        q1: ['java', 'cplusplus'],
        q2: ['html', 'css', 'javascript'],
        q3: ['python', 'java', 'csharp']
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        let score = 0;
        const totalQuestions = Object.keys(correctAnswers).length;

        const formData = new FormData(form);

        // Calculate score
        for (const [question, correct] of Object.entries(correctAnswers)) {
            // Get all selected values for this question
            const selected = formData.getAll(question);

            // Check if selected matches correct exactly
            const isCorrect = selected.length === correct.length &&
                              correct.every(val => selected.includes(val));

            if (isCorrect) {
                score++;
            }
        }

        // Display results
        resultsContainer.style.display = 'block';

        if (score === totalQuestions) {
            resultsContainer.style.color = 'var(--success-color)';
            resultsContainer.textContent = `Perfect! You scored ${score} out of ${totalQuestions}.`;
        } else {
            resultsContainer.style.color = '#ffffff';
            resultsContainer.textContent = `You scored ${score} out of ${totalQuestions}. Keep practicing!`;
        }
    });
});

